// Node: "Inject Cards" - Runs once for all items

const CARDS_CONTAINER_ID = "86afe30";
// Lexington remains proposed and under School Committee review. Remove this
// named exception only after an approved change to its admissions status.
const INQUIRY_ONLY_PROGRAMS = {
  "51223157555": {
    url: "https://alpha.school/boston-suburbs/",
    label: "Stay In-the-Know",
    status: "Proposed · under School Committee review · not open or enrolling"
  }
};

// -------- Get definitions from previous nodes --------
const cardTemplate = $('Set Card Template').first().json.cardTemplate;
const SCHOOL_ORDER = $('Set School Order').first().json.schoolOrder;
const imageMap = $('Set Images').first().json.imageMap;

// -------- Extract & Sort Schools --------
// If Aggregate returns a single item:
const rawSchools = $('Aggregate').first().json.schools || [];

// If Aggregate might return multiple items instead, use this instead:
// const rawSchools = $('Aggregate').all().flatMap(i => i.json.schools || []);

const schools = rawSchools.map(item => item.program);

// -------- Sorting --------
schools.sort((a, b) => {
  const orderA = SCHOOL_ORDER.indexOf(a.form_program_interest);
  const orderB = SCHOOL_ORDER.indexOf(b.form_program_interest);

  if (orderA !== -1 && orderB !== -1) return orderA - orderB;
  if (orderA !== -1) return -1;
  if (orderB !== -1) return 1;
  return (a.id || 0) - (b.id || 0);
});

// -------- Helpers --------
let idCounter = Date.now();

function generateId() {
  return (idCounter++).toString(16).slice(-7);
}

function clone(obj) {
  return JSON.parse(JSON.stringify(obj));
}

function safeStr(value, fallback = "") {
  if (value === null || value === undefined || value === "") return fallback;
  return String(value).trim();
}

function formatTuition(amount) {
  if (!amount) return "Contact for pricing";
  const num = parseInt(amount, 10);
  if (isNaN(num)) return "Contact for pricing";
  return "$" + num.toLocaleString("en-US");
}

function formatAddress(address) {
  if (address) return address;
  return "Location announced soon!";
}

function formatSchoolName(school, gradeLevels) {
  const name = safeStr(school, "Alpha School");
  let grades = safeStr(gradeLevels);
  if (grades && grades !== "-") {
    grades = grades.replace(/PreK/gi, "PK");
    return `${name} (${grades})`;
  }
  return name;
}

function getImageUrl(formProgramInterest) {
  return imageMap[formProgramInterest] || imageMap["_default"];
}

function getPageUrl(program) {
  return program.website || 
    `https://alpha.school/${(program.form_program_interest || '').replace(/_/g, '-')}/`;
}

function getApplyUrl(program) {
  if (program.admission_link) return program.admission_link;
  if (program.submission_campus) {
    return `https://alpha.school/application/?submission_campus=${program.submission_campus}`;
  }
  return "https://alpha.school/application/";
}

// -------- Build Card --------
function buildCard(program) {
  const card = clone(cardTemplate.container);
  card.id = generateId();

  // Raleigh current service is K-8; K-10 applications are for Fall 2027. Matt Barge approval 2026-10-09, APEX cmv11wrf9000306jmrcsuxxxx. Keep HubSpot shared range unchanged pending cmu4g13kc00000agmdogkxihp.
  const websiteGrades = String(program.id) === "29735717555" ? "K-8" : program.grade_levels;
  const schoolName = formatSchoolName(program.school, websiteGrades);
  const inquiryOnly = INQUIRY_ONLY_PROGRAMS[String(program.id)];
  const isWaitlist = !inquiryOnly && /(?:2026[–-]27 enrollment is currently on a waitlist basis|accepting applications for our 2026[–-]27 waitlist)/i.test(safeStr(program.website_campus_intro));
  const address = formatAddress(program.school_address);
  const tuition = formatTuition(program.tuition_usd_yearly);
  const pageUrl = getPageUrl(program);
  const applyUrl = inquiryOnly ? inquiryOnly.url : getApplyUrl(program);
  const imageUrl = getImageUrl(program.form_program_interest);

  const image = clone(cardTemplate.image);
  image.id = generateId();
  image.settings.image.url = imageUrl;
  image.settings.link.url = pageUrl;

  const schoolNameWidget = clone(cardTemplate.schoolName);
  schoolNameWidget.id = generateId();
  schoolNameWidget.settings.editor = `<p>${schoolName}</p>` + (isWaitlist ? `<p><strong>2026–27 Waitlist</strong><br>Apply for future enrollment through our admissions application.</p>` : "");

  const addressWidget = clone(cardTemplate.address);
  addressWidget.id = generateId();
  addressWidget.settings.editor = `<p>${address}</p>` + (inquiryOnly ? `<p>${inquiryOnly.status}</p>` : "");

  const tuitionWidget = clone(cardTemplate.tuition);
  tuitionWidget.id = generateId();
  tuitionWidget.settings.editor = `<strong>Tuition:</strong> ${tuition}`;

  const viewButton = clone(cardTemplate.viewButton);
  viewButton.id = generateId();
  viewButton.settings.link.url = pageUrl;

  const applyButton = clone(cardTemplate.applyButton);
  applyButton.id = generateId();
  applyButton.settings.link.url = applyUrl;
  if (inquiryOnly) applyButton.settings.text = inquiryOnly.label;
  else if (isWaitlist) applyButton.settings.text = "Apply for waitlist";

  const spacer = clone(cardTemplate.spacer);
  spacer.id = generateId();

  card.elements = [
    image,
    schoolNameWidget,
    addressWidget,
    tuitionWidget,
    viewButton,
    applyButton,
    spacer
  ];

  return card;
}

// -------- Build All Cards --------
const cards = schools.map(program => buildCard(program));

// -------- Inject into Elementor --------
const elementorRaw = $('Get a page').first().json.meta._elementor_data;
const data = JSON.parse(elementorRaw);

function findAndInjectCards(elements) {
  for (const el of elements || []) {
    if (el.id === CARDS_CONTAINER_ID) {
      el.elements = cards;
      return true;
    }
    if (el.elements?.length && findAndInjectCards(el.elements)) {
      return true;
    }
  }
  return false;
}

const found = findAndInjectCards(data);

if (!found) {
  throw new Error(`Container with ID "${CARDS_CONTAINER_ID}" not found`);
}

// -------- Return SINGLE item --------
return [
  {
    json: {
      elementor_data: data,
      cards_injected: cards.length,
      schools_order: schools.map(p => safeStr(p.school, "Unknown"))
    }
  }
];
